STOP = {'the', 'a', 'an', 'and', 'is', 'was', 'it', 'to', 'of', 'for', 'on',
        'in', 'with', 'this', 'but', 'at', 'by', 'my', 'me', 'i', 'not', 'no'}

def lemma(w):
    for suf, cut in [('ing', 3), ('ed', 2), ('es', 2), ('s', 1)]:
        if len(w) > 4 and w.endswith(suf):
            return w[:-cut]
    return w

kept = [lemma(w) for w in tokens if w not in STOP]
print(len(tokens), '->', len(kept))
print(Counter(kept).most_common(6))

